function palindromePartition(s, k) {
  const n = s.length;
  const cost = Array.from({ length: n }, () => new Array(n).fill(0));

  for (let length = 2; length <= n; length++) {
    for (let left = 0; left + length - 1 < n; left++) {
      const right = left + length - 1;
      const inner = length > 2 ? cost[left + 1][right - 1] : 0;
      cost[left][right] = inner + (s[left] === s[right] ? 0 : 1);
    }
  }

  const dp = Array.from({ length: k + 1 }, () => new Array(n + 1).fill(Infinity));
  dp[0][0] = 0;

  for (let parts = 1; parts <= k; parts++) {
    for (let end = parts; end <= n; end++) {
      for (let start = parts - 1; start < end; start++) {
        const candidate = dp[parts - 1][start] + cost[start][end - 1];
        dp[parts][end] = Math.min(dp[parts][end], candidate);
      }
    }
  }
  return dp[k][n];
}

brute:
function palindromePartition(s, k) {
  const fix = text => {
    let changes = 0;
    for (let i = 0, j = text.length - 1; i < j; i++, j--) if (text[i] !== text[j]) changes++;
    return changes;
  };
  const split = (rest, pieces) => {
    if (pieces === 1) return fix(rest);
    let best = Infinity;
    for (let cut = 1; cut <= rest.length - pieces + 1; cut++) {
      best = Math.min(best, fix(rest.slice(0, cut)) + split(rest.slice(cut), pieces - 1));
    }
    return best;
  };
  return split(s, k);
}

