function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 100 : 1 + Math.floor(rand() * 10);
  const letters = large ? 2 + Math.floor(rand() * 25) : 1 + Math.floor(rand() * 4);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * letters));
  const k = 1 + Math.floor(rand() * n);
  return [s, k];
}
